/**
 * Zonas reales de operación en Querétaro.
 * Requiere que GeoCatalogSeeder se haya ejecutado primero (municipios cargados).
 *
 * Uso: php artisan db:seed --class=ZoneSeeder
 */
class ZoneSeeder extends Seeder
{
