)',
            ],
            [
                'name' => 'Zona Demo 1',
                'description' => '',
                'postal_code' => '76060',
                'municipality_id' => $municipioQro?->id,
                'status' => ZoneStatus::Active,
                'polygon' => 'SRID=4326;POLYGON((-100.3544343 20.5984652,-100.3546312 20.598234,-100.3551394 20.5974269,-100.3553022 20.597305,-100.3553832 20.5972557,-100.355472 20.5972288,-100.3555561 20.597211,-100.3556482 20.5972042,-100.3557958 20.5972169,-100.3559445 20.5972629,-100.3561227 20.5973432,-100.3564841 20.5975019,-100.3570012 20.5977271,-100.3573677 20.5979137,-100.3576424 20.5980768,-100.3581088 20.5982917,-100.3589031 20.5985885,-100.3591934 20.5987471,-100.3596904 20.5990625,-100.3603515 20.5994851,-100.3608488 20.5998553,-100.3613445 20.6000735,-100.3635724 20.6010335,-100.3637844 20.6010965,-100.3639404 20.6011289,-100.3646291 20.6012263,-100.3650203 20.601253,-100.3653855 20.6012288,-100.3660976 20.6010996,-100.3663657 20.6010033,-100.3665427 20.6009034,-100.3675257 20.6001611,-100.3675685 20.6001228,-100.3687001 20.5993131,-100.3702495 20.5982288,-100.3709089 20.5977396,-100.3718642 20.5970308,-100.3723617 20.5966711,-100.3657583 20.5901787,-100.365641 20.5900649,-100.3653764 20.5898804,-100.3643117 20.5892533,-100.3639034 20.5889201,-100.3637793 20.5887503,-100.3636873 20.5886183,-100.3622521 20.5890589,-100.3615939 20.5892953,-100.361593 20.5892957,-100.3614799 20.5893486,-100.3605248 20.5897068,-100.3603247 20.5897439,-100.3602281 20.5897486,-100.3599775 20.5897608,-100.3596227 20.5897172,-100.359433 20.5896497,-100.3592309 20.5895775,-100.3569648 20.5885463,-100.3563328 20.588282,-100.3557946 20.5882182,-100.3552771 20.5883182,-100.3539652 20.5887653,-100.3522926 20.5892678,-100.3520757 20.5893197,-100.3518305 20.5893626,-100.351682 20.5893754,-100.3515144 20.5893876,-100.3504348 20.589141,-100.34966 20.588755,-100.3494759 20.5886543,-100.3492195 20.5885553,-100.3489974 20.5884833,-100.3487756 20.5884235,-100.3485229 20.588395,-100.3483245 20.5884016,-100.3480562 20.5884329,-100.347478 20.5885146,-100.346626 20.588658,-100.3434129 20.589208,-100.3430177 20.5892766,-100.3426584 20.5893027,-100.3423061 20.5893128,-100.3391682 20.5899407,-1