            ],
        ];

        foreach ($zones as $data) {
            $data['polygon'] = self::asMultiPolygon($data['polygon']);

            Zone::updateOrCreate(
                ['name' => $data['name']],
                $data,
            );
        }

        // Eliminar el duplicado "Centro Querétaro" creado por error en el primer ZoneSeeder.
        Zone::where('name', 'Centro Querétaro')->whereNotExists(
            fn ($q) => $q->from('properties')->whereColumn('zone_id', 'zones.id')
        )->delete();

        $this->command?->info('ZoneSeeder: '.count($zones).' zona(s) cargadas.');

        if ($municipioQro === null) {
            $this->command?->warn('Municipio "Querétaro" no encontrado — zonas sin municipio. Corré GeoCatalogSeeder primero.');
        }
    }

    /**
     * `zones.polygon` es `geometry(MultiPolygon,4326)` desde la migración
     * 2026_07_04_000000; los literales de abajo se escribieron cuando la columna
     * era `Polygon`, y el cast de Magellan rechaza el tipo simple. Envolvemos el
     * anillo en un MultiPolygon de una sola parte: misma geometría, tipo correcto.
     *
     * Si el literal ya es MULTIPOLYGON se devuelve intacto, así agregar zonas
     * nuevas en el formato correcto no requiere tocar este helper.
     */
    private static function asMultiPolygon(string $wkt): string
    {
        if (str_contains($wkt, 'MULTIPOLYGON')) {
            return $wkt;
        }

        return preg_replace('/POLYGON\s*\((.*)\)\s*$/s', 'MULTIPOLYGON(($1))', $wkt) ?? $wkt;
    }
}
